local cfg_rule_text =
{
	{id=1, name="萤石", menutxt="萤石", location="1、可以在常规装备位上进行镶嵌，常规镶嵌装备包括武器、头盔、铠甲、护手、护腿和靴子\n2、镶嵌成功后会获得对应荧光宝石的属性加成\n3、每个部位最多可以镶嵌三个任意荧光宝石。\n4、同属性的荧光宝石镶嵌累计等级达到指定等级后，会获得特殊技能效果"},
	{id=2, name="石板", menutxt="石板", location="1、可以在常规装备位上进行镶嵌，常规镶嵌装备包括武器、头盔、铠甲、护手、护腿和靴子\n2、镶嵌成功后会获得对应石板的属性加成。\n3、每个部位可以镶嵌一个对应位置远古石板。"},
	{id=3, name="分解", menutxt="分解系统", location="1、所有套装都可以被分解，分解后装备消失\n2、套装分解后会获得粉尘，粉尘可合成镶嵌宝石\n3、有强化、追加等级的装备分解后不会返还强化材料，请谨慎"},
	{id=4, name="红名系统", menutxt="红名系统", location="1、玩家击杀<color=#2EED36>其他非红名玩家</color>时会增加pk值，当PK获得累计到一定量时，玩家就会变为<color=#ED2E2E>恶人状态</color>\n2、恶人状态惩罚：限制使用<color=#ED2E2E>传送功能</color>、限制使用<color=#ED2E2E>商店购买</color>补给、pk值较高时无法<color=#ED2E2E>对玩家造成伤害</color>\n3、恶人状态清洗，PK值会随<color=#2EED36>时间流逝而减少</color>，玩家也可通过<color=#ED2E2E>击杀怪物</color>、<color=#ED2E2E>使用道具</color>等方式清除自身拥有的PK值\n4、防卫状态，在被其他玩家攻击时存在<color=#ED2E2E>防卫反击时间</color>，若在防卫反击时间内将攻击方击杀则被攻击方不会增加PK值"},
	{id=5, name="三倍收益", menutxt="三倍收益", location="1、购买并使用<color=#00FF00>月卡</color>，解锁<color=#00FF00>三倍收益功能</color>，您可在<color=#00FF00>三倍收益界面</color>开启三倍收益时间，获取<color=#00FF00>经验、掉落加成</color>。\n2、在三倍收益界面<color=#00FF00>点击领取</color>即可领取三倍收益时间。\n3、首次拥有日卡后，立即获得<color=#00FF00>4小时</color>三倍收益时间，之后每天可以获得<color=#00FF00>8小时</color>的三倍收益时间，可以自由控制三倍收益开启的时间。\n4、第一次购买月卡时将会立刻增加<color=#00FF00>20小时</color>三倍收益时间。\n5、每天剩余的三倍收益时间能够<color=#00FF00>继承</color>到下一天继续使用，<color=#00FF00>最多可以继承56小时</color>三倍收益时间。\n6、月卡剩余时间大于等于<color=#00FF00>24小时</color>时三倍收益时间将在<color=#00FF00>每天24：00</color>更新。如果今日没有更新三倍收益时间那么三倍收益时间将在您的月卡剩余时间大于等于<color=#00FF00>24小时</color>后发放。"},
	{id=6, name="坐骑", menutxt="坐骑", location="1、使用指定道具可以激活对应的坐骑。\n2、激活坐骑可以获得大量属性。\n3、不同坐骑属性可叠加生效。"},
	{id=7, name="特权", menutxt="特权", location="1、可以消耗月卡时间兑换<color=#00FF00>黄金特权</color>或<color=#00FF00>钻石特权</color>获取超额收益。，\n2、使用<color=#00FF00>黄金特权卡</color>后激活30天<color=#E6E600>黄金特权</color>，\n激活后可获得以下特权，\n<color=#00FF00>·开启黄金线</color>，\n<color=#00FF00>·黄金线中额外享受50%的经验、掉落加成</color>，\n<color=#00FF00>·开启小怪挂机保护功能</color>，\n<color=#00FF00>·背包空间增加160格</color>，\n<color=#00FF00>·开启自动买药</color>，\n<color=#00FF00>·开启随身商店功能</color>，\n<color=#00FF00>·开启加点方案切换</color>，\n3、使用<color=#00FF00>钻石特权卡</color>后激活30天<color=#E6E600>钻石特权</color>，\n激活后可获得以下特权，\n<color=#00FF00>·装备掉率增加100%</color>，\n<color=#00FF00>·怪物经验增加100%</color>，\n<color=#00FF00>·奇迹而回收价增加30%</color>，\n<color=#00FF00>·开启黄金怪挂机功能</color>，\n<color=#00FF00>·背包空间增加320格</color>，\n<color=#00FF00>·开启远程仓库</color>，\n<color=#00FF00>·增加交易行寄售格子5格</color>，"},
	{id=8, name="组队", menutxt="说 明", location="1、队伍最大人数为5人。\n2、组队打怪时，获得怪物的经验会<color=#00FF00>平分</color>给<color=#00FF00>附近战斗</color>的每位队员\n3、队伍人数越多获得的经验加成比例越高，每增加一位成员增加<color=#00FF00>30%</color>经验加成\n4、申请队伍后需队长同意才能入队。"},
	{id=9, name="挂机", menutxt="提 示", location="1、等级达到15级且开通特权后开启离线挂机助手，玩家离线前需先前往挂机点开启自动战斗，离线将持续挂机获得相同收益。\n2、挂机点挂机有被杀风险，被杀后将回城只获得泡点收益。\n3、离线挂机时自动消耗药品，如果已开启特权也正常生效：自动拾取、自动回收、自动买药。\n4、每次离线只累计8小时收益，再次登录可重置时间。\n5、装备、金币、道具类收益在挂机时实时获得经验收益将在上线时统一领取。\n6、同账号多个拥有特权的角色，最近登陆的单角色执行离线挂机。"},
	{id=10, name="装备叠加", menutxt="装备叠加", location="1、只有卓越套装可以使用套装叠加功能。\n2、可以将副装备上拥有但主装备上没有的卓越属性附加在主装备上。\n3、每次叠加只可以把<color=#00FF00>副装备中的一条卓越属性附加到主装备上</color>。\n4、一般装备最多可以叠加获得最多<color=#00FF00>4条卓越词条</color>。\n5、当装备词条达到最大数量后，继续叠加可以<color=#00FF00>随机替换</color>一个<color=#00FF00>卓越词条</color>，被锁定的词条无法被替换。\n6、可消耗幸运宝石<color=#00FF00>提升叠加成功率</color>。\n7、装备叠加后获得的装备将保留两件装备中等级最高的强化和追加值。"},
	{id=11, name="果实系统", menutxt="果实", location="1、果实可为玩家增加基础属性\n2、使用果实后增加的数值为随机值\n3、玩家可消耗奇迹币进行点数重置，重置后的点数可自由增加。"},
	{id=12, name="月卡", menutxt="月卡说明", location="1、购买使用月卡后激活<color=#5CE366FF>30天</color>的月卡特权（掉落<color=#5CE366FF>非绑定道具</color>，正常获取回收收益，激活<color=#5CE366FF>交易行上架</color>功能，解锁<color=#5CE366FF>聊天</color>功能，可选择激活<color=#5CE366FF>黄金特权</color>或<color=#5CE366FF>钻石特权</color>获取超额收益)\n2、月卡到期后可以在<color=#5CE366FF>交易行</color>或<color=#5CE366FF>月卡活动</color>界面购买月卡。"},
	{id=13, name="npc商店", menutxt="商店", location="1、商店是花费金币的地方。\n2、不同商品有不同的购买次数限制。\n3、不同商品的购买次数刷新时间不同。\n4、每月限购：每月可购买次数，购买后需下个月才能继续购买。\n5、每周限购：每周可购买次数，购买后需下周才能继续购买。\n6、每日限购：今日可购买次数，购买后需明日才能继续购买。"},
	{id=14, name="连击技能", menutxt="未激活", location="·激活后，可获得<color=#00FF00>连击技能</color>，使用技能时，可获得连击值，连击值满时，<color=#00FF00>自动</color>释放连击技能。"},
	{id=15, name="邮件", menutxt="说 明", location="1、邮件最多保存15天，请及时处理邮件，谨防丢失。\n2、全部领取：一次性领取所有邮件中的附件。\n3、全部删除：一次性删除所有邮件。\n4、当背包不足时，无法领取邮件。"},
	{id=101, name="变身卡牌镶嵌", menutxt="泰坦武装", location="1、镶嵌卡牌可获得对应卡牌的<color=#00FF00>属性和能力</color>\n一变身泰坦镶嵌至<color=#00FF00>铠甲部位</color>\n一神赋泰坦镶嵌至<color=#00FF00>主副手武器部位</color>\n一赋能泰坦镶嵌至<color=#00FF00>剩余部位</color>\n2、若槽位对应的装备栏没有装备，则该槽位的卡牌<color=#00FF00>不生效</color>\n3、卡牌的获取：兑换页签开泰坦宝箱获取\n4、兑换材料通过野外地图boss<color=#00FF00>掉落</color>获得\n5、回收卡牌可获得材料<color=#00FF00>变身精华</color>\n6、同名变身泰坦卡牌不能重复装备"},
	{id=102, name="变身卡牌牌库", menutxt="牌库说明", location="1、卡牌由低至高分为三种品质：\n<color=#00FFFF>碧蓝</color>、<color=#FFFF00>耀金</color>、<color=#FF4500>赤焱</color>\n2、分为三类：变身、赋能、神赋\n3、变身泰坦在装备上可获得<color=#00FF00>变身技能</color>，变身之后可获得该变身的各种强大技能\n4、赋能与神赋泰坦可获得<color=#00FF00>各种特殊属性词条</color>\n5、同名同等级同品质卡牌可以<color=#00FF00>合成</color>，合成方式为二合一，合成后等级加一\n6、合成满级后能够通过<color=#00FF00>突破</color>晋升为高品质卡牌\n7、回收卡牌可获得材料<color=#00FF00>变身精华</color>"},
	{id=103, name="变身卡牌养成", menutxt="养成说明", location="1、同名同等级同品质卡牌可以<color=#00FF00>合成</color>，合成方式为二合一，合成后等级加一\n2、合成满级后能够通过<color=#00FF00>突破</color>晋升为高品质卡牌，晋升会<color=#00FF00>保留</color>主卡牌的词条，提升词条强度"},
	{id=104, name="变身卡牌孔位解锁", menutxt="开槽说明", location="1、卡牌槽位与穿戴装备阶数或首饰等级有关，<color=#00FF00>阶数或等级越高</color>解锁槽位数量<color=#00FF00>越多</color>"},
	{id=105, name="首充", menutxt="首充豪礼", location="1、直接充值98元可以获得980钻石以及所有的首充奖励\n2、充值6元，可以获得60钻石和第一档奖励，再充值42元，可以获得420钻石和第二档奖励，再充值50元，可以获得500钻石和第三档奖励\n3、充值6元，可以获得60钻石和第一档奖励，再充值92元，可以获得920钻石和第二、三档奖励\n4、充值48元，可以获得480钻石和第一、二档奖励，再充值50元，可以获得500钻石和第三档首充奖励"},
	{id=201, name="宝箱商人", menutxt="宝箱商人", location="1、宝箱商店是花费奇迹币的地方。\n2、不同奇迹宝箱有不同的概率\n3、商店所售卖的宝箱开启后是随机获取里面其中一个装备。\n<color=#23F713>4、商店所售卖的宝箱阶数越高，所能开出的物品的概率越大，套装宝箱会越好</color>"},
	{id=202, name="连击试炼", menutxt="连击试炼", location="1、连击试炼是常驻开启的每日副本玩法，通关上一关后解锁下一关\n2、玩法每天有可通关次数上限，次数上限可通过获取<color=#00FF00>特权卡</color>增加，可通关次数每日0点刷新\n3、副本玩法为在规定时间内击杀指定数量的敌人，达成目标则通关成功，获取通关奖励；反之到时间后未能达成目标则自动失败，获取保底奖励\n4、进入副本需要消耗门票和每日次数，若通关成功，则扣除对应门票和次数，<color=#00FF00>通关失败不扣除次数，但会消耗门票</color>\n5、门票通过击杀野外地图小怪随机掉落\n6、已通关副本可开启扫荡功能，获取特权卡解锁对应特权，即可进行一键扫荡，直接消耗门票和次数获取通关奖励！"},
	{id=203, name="外观幻化", menutxt="幻化", location="1、随着等级的提升可解锁更多可幻化套装\n2、需要消耗材料解锁幻化套装，解锁后可永久使用。"},
	{id=301, name="转盘抽奖", menutxt="抽奖", location="1、抽奖是消耗钻石随机获取奖池奖励的玩法，每次抽取必定会获得奖池内任意一份奖励\n2、奖池内的高品质奖励有可抽到次数限制，抽完后将从奖池内消失\n3、抽奖有免费次数，使用后自动进入倒计时，倒计时结束后免费次数刷新\n4、抽奖有额外奖励，根据在当前奖池的总抽数解锁领取\n5、当期奖池活动结束后，抽奖计数等都将清空，不会累计到下次抽奖活动中，请及时累计次数，获取超值大奖！"},
	{id=15001, name="狼人要塞", menutxt="狼魂要塞", location="1、活动前5分钟为准备阶段，盟主和副盟主可以消耗战盟资金召唤弓箭手，最多召唤5个。\n2、活动总计10波怪物，击杀完所有怪物或者活动时间结束则守卫成功，狼魂雕像被摧毁则守卫失败。\n3、击杀完一波怪物可以获得战盟经验奖励。\n4、每波怪物有几率生成精英怪物，击杀精英怪物可以获得一次学习天赋的机会。\n5、每个方阵的怪物有概率拥有特殊词缀，词缀会提升怪物的能力。"},
	{id=16001, menutxt="参与方式", location="活动期间进入罗兰峡谷即可参与\n盟主需要先进入罗兰攻城战内"},
	{id=16002, menutxt="开启时间", location="每周三和周六的20：00~20：30"},
	{id=16003, menutxt="胜利条件", location="1.摧毁所有城门、守护石像后，进入龙之塔占领罗伦之冠，占领区仅剩1个战盟时，可进行占领\n2.当无任何战盟有占领权时，战盟积分排名第1直接获胜，但是无法成为下次攻城战的守方，盟主也不会出现在名人堂。\n攻城方可获得积分:摧毁建筑、击杀敌人、对敌入造成伤害或治疗队友\n守城方可获得积分:持续守护罗伦之冠、击杀敌人、对敌人造成伤害或治疗队友"},
	{id=16004, menutxt="注意事项", location="1.占领龙之塔内的罗伦之冠后，攻城战也不会因此而结束，攻城时间结束时，最后占领罗伦之冠的战盟才算最后胜利的战盟\n2.每层守护石像被攻破后，攻城方的出生点会变化，建议防守方提早进入城池\n3.攻城战期间，无法进行战盟职位变更，无法加入或退出战盟\n4.每次攻城战开启时，系统自动收回上次发放的称号/坐骑\n5.攻城战结束后将通过邮件发放战盟奖励、积分奖励，个人积分低于300时不获得奖励"},
	{id=16005, menutxt="攻城战说明", location="1、攻城战共分为<color=#00FF00>4个阶段</color>。\n2、1~3阶段，玩家分为<color=#00FF00>攻方和守方</color>两个阵营；攻方针对城门进行进攻方案，攻破外城门、中城门、内城门后，即可进行下一阶段的任务；守方则在对应的阶段，守住城门，抵抗攻方。\n3、4阶段时，玩家不在按照攻守方进行阵营划分，而是<color=#00FF00>每个战盟为一个独立的阵营</color>；玩家需要前往<color=#00FF00>龙之塔</color>，占领<color=#00FF00>罗兰之冠</color>，为自己的战盟夺得胜利！"},
	{id=19001, name="大秘境", menutxt="", location="当前副本评分为s时，可在当前副本开启扫荡"},
	{id=19002, name="大秘境", menutxt="大天使秘境评分规则", location="<color=#008080>1、大天使秘境等级为<color=#00FF00>1级到15级</color>时：</color>\n7分钟以内通关为<color=#00FF00>SSS级评分</color>，钥匙等级升<color=#00FF00>3级</color>；\n7分钟到8分钟通关为<color=#00FF00>SS级评分</color>，钥匙等级升<color=#00FF00>2级</color>；\n8分钟到9分钟通关为<color=#00FF00>S级评分</color>，钥匙等级升<color=#00FF00>1级</color>；\n9分钟以外通关为<color=#00FF00>B级评分</color>，钥匙等级<color=#00FF00>降低1级</color>。\n\n<color=#008080>2、大天使秘境等级为<color=#00FF00>16级到45级</color>时：</color>\n8分钟以内通关为<color=#00FF00>SSS级评分</color>，钥匙等级升<color=#00FF00>3级</color>；\n8分钟到9分钟通关为<color=#00FF00>SS级评分</color>，钥匙等级升<color=#00FF00>2级</color>；\n9分钟到10分钟通关为<color=#00FF00>S级评分</color>，钥匙等级升<color=#00FF00>1级</color>；\n10分钟以外通关为<color=#00FF00>B级评分</color>，钥匙等级<color=#00FF00>降低1级</color>。\n中途退出副本，钥匙等级也会<color=#00FF00>降低1级</color>；\n当前秘境等级上限为<color=#00FF00>45级</color>。"},
	{id=27001, name="猎魔积分争霸赛", menutxt="猎魔积分争霸赛", location="1、玩家击杀<color=#00FF00>黄金怪</color>和<color=#00FF00>BOSS</color>，可获得<color=#00FF00>杀怪积分</color>\n2、全服所有玩家的杀怪积分会根据<color=#00FF00>一定比例</color>，转化成<color=#00FF00>猎魔勋章</color>，进入猎魔勋章池\n3、全服玩家根据杀怪积分排名，共同瓜分猎魔勋章池，<color=#00FF00>排名越高</color>的玩家，<color=#00FF00>瓜分的比例</color>越多\n4、猎魔勋章可在<color=#00FF00>猎魔勋章商店</color>中兑换<color=#00FF00>大量养成奖励</color>和<color=#00FF00>限定唯一时装坐骑</color>，猎魔勋章会在赛季结束时清空，同时猎魔勋章商店在新赛季开启后会上架新的商品。\n5、击杀同等级段的怪物有更多的杀怪积分，击杀低等级段的怪物会<color=#00FF00>积分衰减</color>\n6、<color=#00FF00>每天21点</color>进行积分结算，奖励通过<color=#00FF00>邮件</color>下发，并且之后的杀怪不进行积分统计。<color=#00FF00>每日0点</color>重置活动，开始进行杀怪统计。\n7、数据量较大，会有<color=#00FF00>1分钟左右</color>的延迟时间"},
	{id=27002, name="猎魔积分争霸赛", menutxt="猎魔积分争霸赛规则详情"},
	{id=28001, name="大天使突破", menutxt="突破", location="1.穿戴大天使装备后，对野外怪物造成伤害即可获得大天使经验，经验足够时大天使装备将自动升级。\n2.大天使装备分为<color=#00FF00>1-9阶</color>，每个等阶有<color=#00FF00>等级上限</color>，当达到<color=#00FF00>等级上限</color>时，需要<color=#00FF00>突破</color>大天使装备，提高<color=#00FF00>等阶</color>才能提高<color=#00FF00>等级上限</color>，继续获得经验。\n3.<color=#00FF00>等级上限</color>可以在大天使装备的tips上查看。\n4.突破需要消耗一定的材料，材料不足时无法突破。"},
	{id=29001, name="大天使圣杯", menutxt="圣杯融合与强化", location="1.当大天使装备达到一定阶数时，可以融合一个对应阶数的<color=#00FF00>圣杯</color>。\n2.圣杯<color=#00FF00>融合</color>后，可以进行圣杯<color=#00FF00>强化</color>，每次强化会必定强化<color=#00FF00>1次主属性</color>和<color=#00FF00>随机1条副属性</color>。"},
	{id=30001, name="冰风堡攻城战", menutxt="冰风堡攻城战", location="1.每周五20：00—21：00开启活动，对冰风谷右上角城堡中的王座进行占领，坚持占领到最后的战盟将获得胜利！\n2.进入占领状态后，角色将无法行动直至死亡或主动取消占领。\n3.当一名角色持续占领时间≥180s，则视为该角色所属战盟完成占领。\n4.整场活动中击杀玩家数量最多的前五名玩家将获得额外的MVP奖励"},
	{id=31001, name="血色城堡", menutxt="血色城堡", location="1、开启时间:从13:00开始，每2小时开启一场一天总开启6场。\n2、不同等级可进入不同层血色城堡，每次进入血色城堡需消耗1个透明披风。\n3、血色城堡内怪物密集、刷新频率高、击杀怪物经验多，此副本内挂机打怪可获得大量经验\n4、完成血色城堡任务:攻破城门、打开水晶棺交还大天使之武器后，可额外获得奖励。\n5、血色城堡可组队一起进入，击杀怪物经验平分。队伍内人数越多，经验加成越高，2人+20%，3人队+40%，4人队+60%，5人队+80%，怪物经验共享有效范围为20码。\n6、为保证队伍其他成员收益，此副本内限制组队玩家对金币/白装的拾取设置，单人进入不限制。"},
	{id=32001, name="恶魔广场", menutxt="恶魔广场", location="1、开启时间:从14:00开始，每2小时开启一场一天总开启6场。\n2、不同等级可进入不同层恶魔广场，每次进入恶魔广场需消耗对应数量的恶魔通行证。\n3、恶魔广场内怪物密集、刷新频率高、击杀怪物经验多，此副本内挂机打怪可获得大量经验。\n4.恶魔广场可组队进入，击杀怪物均分经验。\n5.组队进入恶魔广场后，击杀怪物可获得积分，结算时根据积分可获得额外奖励。\n6.根据积分数量对组队成员进行排名，恶魔广场结算时根据排名前三名可获得额外奖励。"},
	{id=33001, name="面对面交易", menutxt="说 明", location="1、面对面交易货币税率为10%\n2、面对面交易双方需要在一定距离内进行\n3、面对面交易存在特权限制，需要开通特权\n4、进行交易的道具与货币必须为支持面对面交易的道具且为非绑状态\n5、交易存在最大交易时间，超过这个时间交易超时将关闭界面\n6、进入交易确认环节后任意一方解锁交易栏，双方均会解锁"},
	{id=34001, name="挂机", menutxt="变 强", location="1.使用：<color=#1add1f>更高级的药水</color>\n\n2.提升：<color=#1add1f>防御值</color>\n\n3.提升：<color=#1add1f>生命恢复速度</color>\n\n4.提升：<color=#1add1f>最大生命值</color>\n\n5.提升：<color=#1add1f>伤害减少</color>，<color=#1add1f>伤害吸收</color>"},
	{id=401, name="卡利玛神庙", menutxt="卡利玛神庙", location="1、<color=#1add1f>单人副本</color>，每日可进入3次，<color=#1add1f>会员玩家可获得额外进入次数</color>，副本限时20分钟。\n2、每次进入卡利玛神庙需消耗1个<color=#1add1f>对应级数的失落的地图</color>。\n3、击杀boss昆顿后，人物将在<color=#1add1f>30s</color>后自动离开副本\n4、卡利玛神庙内怪物较少、击杀后不会重生，但是爆率极高，最低掉落卓越品质装备，在卡利玛神庙有更高几率获得优质装备。\n5、通关后可解锁对应层数的扫荡功能，在消耗失落的地图的基础上，额外消耗卡利玛秘钥（钻石商城）即可快速扫荡，并获得Boss昆顿的掉落奖励。"},
}

local defaults = {name="攻城战", location="一、积分奖励\n1、积分奖励勋章为<color=#00FF00>动态显示</color>，显示勋章数量为实际可获得的数量\n2、有该档位排名后，才会显示该排名段的奖励预览\n3、排名前10玩家更有<color=#00FF00>限时特殊称号</color>\n4、排名前100以后的玩家，在获得<color=#00FF00>19999杀怪积分</color>后，领取29999勋章奖励，<color=#00FF00>不瓜分奖池</color>\n\n二、杀怪积分转化详情\n<color=#00FF00>0分</color>到<color=#00FF00>350000分</color>段，转化比率为：<color=#00FF00>60%</color>\n<color=#00FF00>350000分</color>到<color=#00FF00>690000分</color>段，转化比率为：<color=#00FF00>100%</color>\n<color=#00FF00>690000分</color>到<color=#00FF00>1380000分</color>段，转化比率为：<color=#00FF00>130%</color>\n<color=#00FF00>1380000分</color>到<color=#00FF00>2070000分</color>段，转化比率为：<color=#00FF00>160%</color>\n<color=#00FF00>2070000分</color>到<color=#00FF00>3110000分</color>段，转化比率为：<color=#00FF00>180%</color>\n<color=#00FF00>3110000分</color>到<color=#00FF00>4150000分</color>段，转化比率为：<color=#00FF00>200%</color>\n<color=#00FF00>4150000分</color>到<color=#00FF00>5530000分</color>段，转化比率为：<color=#00FF00>220%</color>\n<color=#00FF00>5530000分</color>到<color=#00FF00>6910000分</color>段，转化比率为：<color=#00FF00>240%</color>\n<color=#00FF00>6910000分</color>到<color=#00FF00>8640000分</color>段，转化比率为：<color=#00FF00>260%</color>\n<color=#00FF00>8640000分</color>到<color=#00FF00>10370000分</color>段，转化比率为：<color=#00FF00>280%</color>\n<color=#00FF00>10370000分</color>到<color=#00FF00>12440000分</color>段，转化比率为：<color=#00FF00>300%</color>\n<color=#00FF00>12440000分</color>到<color=#00FF00>15210000分</color>段，转化比率为：<color=#00FF00>310%</color>\n<color=#00FF00>15210000分</color>到<color=#00FF00>17980000分</color>段，转化比率为：<color=#00FF00>320%</color>\n<color=#00FF00>17980000分</color>到<color=#00FF00>21430000分</color>段，转化比率为：<color=#00FF00>330%</color>\n<color=#00FF00>21430000分</color>到<color=#00FF00>25580000分</color>段，转化比率为：<color=#00FF00>340%</color>\n<color=#00FF00>25580000分</color>到<color=#00FF00>31800000分</color>段，转化比率为：<color=#00FF00>350%</color>\n<color=#00FF00>31800000分</color>以上，转化比率为：<color=#00FF00>360%</color>"}
